css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.1;letter-spacing:-.025em}
p{margin:0}a{color:inherit;text-decoration:none}ol,ul{margin:0;padding:0;list-style:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}.gr{background:var(--g);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p,.gr p{color:var(--mute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}.btn.xl{padding:18px 32px;font-size:17px}
.b-l{background:var(--l);color:var(--k)}.b-o{border-color:#ffffff40;color:#fff}.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:22px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.dk .eb{color:var(--l)}.lt .eb,.gr .eb{color:var(--ink)}.lt .eb::before,.gr .eb::before{background:var(--k)}
.h2{font-size:clamp(30px,4.4vw,56px);letter-spacing:-.035em;line-height:1.05}
.sh{max-width:720px;margin-bottom:48px}.sh p{margin-top:16px;font-size:17px;max-width:600px}
.cpl{display:inline-block;font:600 12px Inter;background:var(--l);color:var(--k);padding:5px 13px;border-radius:99px}
.fine{margin-top:20px;font-size:14px}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;font-size:14.5px;color:#d0d0d4}nav ul a:hover,nav ul a.on{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px}
/* motion */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
.mk{display:block;overflow:hidden;padding-bottom:.1em;margin-bottom:-.1em}.mk>span{display:block}
.js .mk>span{transform:translateY(110%);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.js .in .mk>span,.js .mk.in>span{transform:none}
/* ===== PROJECT PRODUCT UI TOKENS (swap per project) ===== */
.pj{--bg:#F4EFE6;--sf:#fff;--ac:#B98B4A;--dp:#12332E;--tx:#1d1d1b;--mu:#6d6a62;--pl:#e0d9cb;--im1:#2d5a52;--im2:#12332E;background:var(--bg);color:var(--tx);font:400 11px/1.4 Inter,sans-serif}
.pj *{color:inherit}.pj .sr{font-family:Georgia,'Times New Roman',serif;font-weight:400;letter-spacing:-.01em;color:var(--dp)}
.pj .bt{display:inline-block;background:var(--dp);color:#F4EFE6;border-radius:8px;padding:8px 14px;font:600 11px Inter;white-space:nowrap}.pj .bt.a{background:var(--ac);color:#1d1d1b}.pj .bt.o{background:transparent;border:1px solid var(--dp);color:var(--dp)}
.pj .cd{background:var(--sf);border:1px solid var(--pl);border-radius:12px;padding:10px}
.pj .im{border-radius:8px;background:linear-gradient(135deg,var(--im1),var(--im2));min-height:44px;position:relative}
.pj .ln{height:6px;border-radius:3px;background:#ddd6c7;margin-top:6px}.pj .ln.s{width:60%}.pj .ln.d{background:var(--dp);width:70%;height:8px}
.pj .fl{border:1px solid var(--pl);border-radius:8px;padding:7px 9px;font-size:10px;color:var(--mu);background:var(--sf)}.pj .fl b{display:block;color:var(--tx);font-size:11px;font-weight:600}
.pj .chip{font-size:10px;padding:3px 9px;border-radius:99px;background:#e9e2d2;display:inline-block}.pj .chip.on{background:var(--dp);color:#F4EFE6}
.pj .row{display:flex;align-items:center;gap:8px}.pj .sp{margin-left:auto}
.pj .g3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.pj .g2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.pj .stk{display:flex;flex-direction:column;gap:8px}
/* hero */
.hero{padding:80px 0 0;background:radial-gradient(circle at 85% 0,#C7FF3F12,transparent 45%),var(--k);overflow:hidden}
.hero h1{font-size:clamp(34px,5.4vw,72px);line-height:1.02;letter-spacing:-.04em;max-width:900px}
.hero .sub{margin:22px 0 22px;font-size:clamp(17px,2vw,20px);max-width:620px;color:#d6d6da}
.tags{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:56px}.tags li{font-size:13px;font-weight:500;padding:6px 14px;border-radius:99px;background:var(--k2);border:1px solid var(--dline);color:#e0e0e4}
.hv{position:relative;padding-bottom:70px}
.hv .cpl{position:absolute;left:18px;top:-14px;z-index:3}
.brw{background:var(--k2);border:1px solid var(--dline);border-radius:18px;overflow:hidden;box-shadow:0 30px 70px #000b}
.top{display:flex;align-items:center;gap:6px;padding:12px 16px;border-bottom:1px solid var(--dline)}.top b{width:9px;height:9px;border-radius:50%;background:#333}.top .url{margin-left:12px;font-size:12px;color:var(--dmute);background:#1a1a1e;border-radius:99px;padding:4px 14px}
.site .nv{display:flex;align-items:center;gap:22px;padding:14px 28px;border-bottom:1px solid var(--pl);font-size:12px}.site .nv .sr{font-size:17px}
.site .hb{margin:18px 28px 0;border-radius:14px;padding:44px 40px 70px;position:relative;background:linear-gradient(135deg,var(--im1),var(--im2))}
.site .hb h3{font:400 clamp(26px,4vw,52px)/1.05 Georgia,serif;color:#F4EFE6;letter-spacing:-.02em;max-width:480px}.site .hb p{color:#d8d2c3;font-size:13px;margin-top:10px;max-width:340px}
.site .bk{position:absolute;left:28px;right:28px;bottom:-26px;background:#fff;border:1px solid var(--pl);border-radius:14px;padding:12px 14px;display:grid;grid-template-columns:repeat(3,1fr) auto;gap:10px;align-items:center;box-shadow:0 14px 30px #0003}
.site .rms{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:50px 28px 28px}.site .rms .im{height:90px}
.hv .ph{position:absolute;right:28px;bottom:0;--pw:190px;transform:rotate(2deg)}
.hv .ai{position:absolute;left:44px;bottom:12px;background:var(--k);border:1px solid var(--l);border-radius:99px;padding:10px 16px;font-size:13px;color:#fff;display:flex;gap:10px;align-items:center;box-shadow:0 14px 30px #0008}.hv .ai::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
/* phone/tablet */
.ph{--pw:200px;width:var(--pw);aspect-ratio:9/18.5;background:#1a1a1e;border:2px solid #34343a;border-radius:34px;padding:8px;position:relative;flex:none;box-shadow:0 24px 50px #000a}
.ph .sc{height:100%;border-radius:26px;overflow:hidden;padding:2.6em 1em 1em;font-size:calc(var(--pw)/20);display:flex;flex-direction:column;gap:.7em;position:relative}
.ph .sc::before{content:"";position:absolute;top:.8em;left:50%;transform:translateX(-50%);width:5em;height:1.3em;border-radius:1em;background:#111}
.tab{--pw:240px;width:var(--pw);aspect-ratio:3/4;background:#1a1a1e;border:2px solid #34343a;border-radius:24px;padding:10px;box-shadow:0 24px 50px #000a;flex:none}
.tab .sc{height:100%;border-radius:16px;overflow:hidden;padding:1.3em;font-size:calc(var(--pw)/22);display:flex;flex-direction:column;gap:.8em}
/* overview */
.ov{display:grid;grid-template-columns:1fr 1fr;gap:56px}
.ov h3{font:600 13px Inter;letter-spacing:.1em;margin-bottom:16px}.ov p{font-size:17px;margin-bottom:14px}
.info{display:grid;grid-template-columns:repeat(5,1fr);gap:0;margin-top:56px;border-top:2px solid var(--k)}
.info div{padding:20px 20px 0 0}.info small{display:block;font:600 11.5px Inter;letter-spacing:.1em;color:var(--mute);margin-bottom:8px}.info b{font:600 15px Sora;line-height:1.4}
/* problem */
.st{font-size:clamp(28px,4.6vw,60px);letter-spacing:-.04em;line-height:1.06;max-width:960px;margin-bottom:56px}.st span{color:#6f6f75}
.pr li{display:grid;grid-template-columns:70px 1fr;gap:12px;padding:22px 0;border-top:1px solid var(--dline);font-size:clamp(17px,1.8vw,21px);color:#e4e4e7;transition:padding-left .3s}
.pr li:hover{padding-left:12px}.pr li:last-child{border-bottom:1px solid var(--dline)}.pr li b{font:600 13px Sora;color:var(--l);padding-top:6px}
/* strategy */
.mp{display:grid;grid-template-columns:repeat(5,1fr);gap:0}
.mc{position:relative;margin-right:30px;background:#fff;border:1px solid var(--line);border-radius:20px;padding:20px 18px}
.mc:last-child{margin-right:0;background:var(--k);color:#fff;border-color:var(--k)}
.mc::after{content:"→";position:absolute;left:100%;top:50%;width:30px;transform:translateY(-50%);text-align:center;font:600 18px Sora;color:var(--ink)}.mc:last-child::after{display:none}
.mc h4{font:600 11.5px Inter;letter-spacing:.1em;color:var(--mute);margin-bottom:14px}.mc:last-child h4{color:var(--l)}
.mc li{font-size:14px;padding:9px 0;border-top:1px solid var(--line)}.mc:last-child li{border-color:var(--dline);color:#e4e4e7}
/* ux flow */
.fw{display:grid;grid-template-columns:repeat(5,1fr);gap:0}
.fs{position:relative;margin-right:26px}.fs:last-child{margin-right:0}
.fs::after{content:"→";position:absolute;left:100%;top:60px;width:26px;text-align:center;font:600 18px Sora}.fs:last-child::after{display:none}
.fs .pj{border-radius:16px;padding:14px;min-height:150px;border:1px solid var(--line)}
.fs h4{font:600 13px Sora;letter-spacing:.06em;margin:16px 0 4px}.fs p{font-size:14px}
/* design system */
.dsw{border:1.5px dashed #3a3a40;border-radius:28px;padding:18px}
.dsw>.cpl{margin:2px 0 14px 4px;background:#e9e2d2}
.dsb{border-radius:18px;padding:26px}
.dsg{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.dst{background:#fff;border:1px solid var(--pl);border-radius:16px;padding:18px}
.dst>small{display:block;font:600 10.5px Inter;letter-spacing:.1em;color:var(--mu);margin-bottom:14px}
.dst.w2{grid-column:span 2}
.sw{display:flex;gap:8px}.sw i{flex:1;aspect-ratio:1;border-radius:10px;border:1px solid var(--pl)}.hx{display:flex;gap:8px;font-size:9.5px;color:var(--mu);margin-top:8px}.hx span{flex:1}
.aa{font:400 52px/1 Georgia,serif;color:var(--dp)}.dst .bd{font-size:12px;color:var(--mu);margin-top:8px}
.ic{display:flex;gap:12px}.ic svg{width:26px;height:26px;stroke:var(--dp);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.spc{display:flex;align-items:flex-end;gap:8px}.spc i{background:var(--ac);width:16px;border-radius:3px}
.sepn{display:flex;justify-content:space-between;gap:12px;font:600 11px Inter;letter-spacing:.08em;margin:14px 4px 0;color:var(--dmute)}
/* features */
.fr{display:grid;grid-template-columns:1fr 1.2fr;gap:56px;align-items:center;padding:56px 0;border-top:1px solid var(--line)}
.fr:first-of-type{border-top:0;padding-top:0}.fr:nth-of-type(even) .fx{order:2}
.fr .no{font:600 13px Sora;color:var(--mute);margin-bottom:12px}.fr h3{font-size:clamp(24px,2.8vw,36px);letter-spacing:-.03em;margin-bottom:12px}.fr p{font-size:16.5px;max-width:420px}
.fv{border-radius:24px;background:var(--k);padding:26px;min-height:300px;display:flex;align-items:center;justify-content:center}
.fv .pj{width:100%;max-width:440px;border-radius:16px;padding:16px;font-size:12px}
.msg{padding:9px 12px;border-radius:12px;font-size:12px;max-width:85%}.msg.u{background:#e9e2d2;align-self:flex-end}.msg.a{background:var(--dp);color:#F4EFE6}
.mic{width:64px;height:64px;border-radius:50%;background:var(--ac);display:grid;place-items:center;margin:6px auto}.mic i{width:18px;height:28px;border-radius:9px;background:var(--dp)}
.wv{display:flex;align-items:center;justify-content:center;gap:4px;height:34px}.wv i{width:4px;border-radius:2px;background:var(--dp)}
/* ai */
.aiflow{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-bottom:40px}
.an{position:relative;margin-right:30px;background:var(--k2);border:1px solid var(--dline);border-radius:18px;padding:22px 18px}.an:last-child{margin-right:0;border-color:var(--l)}
.an::after{content:"→";position:absolute;left:100%;top:50%;width:30px;transform:translateY(-50%);text-align:center;color:var(--l);font:600 18px Sora}.an:last-child::after{display:none}
.an small{font:600 11px Inter;letter-spacing:.1em;color:var(--l)}.an h4{font-size:17px;color:#fff;margin:10px 0 8px}.an p{font-size:14px}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.cols>div{border:1px solid var(--dline);border-radius:20px;padding:26px;background:var(--k2)}.cols h4{font-size:16px;margin-bottom:14px;color:#fff}
.cols li{padding:10px 0;border-top:1px solid var(--dline);color:#d8d8dc;font-size:15px;display:flex;gap:10px}.cols li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--l);margin-top:9px;flex:none}
/* responsive */
.dv{display:flex;align-items:flex-end;justify-content:center;gap:22px;background:var(--k);border-radius:28px;padding:40px 30px}
.dv .brw{flex:1;max-width:560px}.dv .brw .site .hb{padding:26px 24px 56px;margin:14px 18px 0}.dv .brw .site .hb h3{font-size:24px}.dv .rms{padding:44px 18px 18px;gap:8px}
.dl{display:flex;gap:22px;justify-content:center;margin-top:18px;font:600 12px Inter;letter-spacing:.1em;color:var(--mute)}
/* tech */
.tg{display:grid;grid-template-columns:repeat(6,1fr);gap:20px;border-top:1px solid var(--line);padding-top:30px}
.tg h4{font:600 11.5px Inter;letter-spacing:.1em;color:var(--mute);margin-bottom:14px}
.tg span{display:block;padding:10px 0;border-bottom:1px solid var(--line);font:600 15px Sora}
/* decisions */
.dt{width:100%}.dt .r{display:grid;grid-template-columns:1fr 1fr 1fr;gap:28px;padding:22px 0;border-top:1px solid var(--dline)}
.dt .r:last-child{border-bottom:1px solid var(--dline)}.dt .hd{padding:0 0 14px;border-top:0}
.dt .hd span{font:600 11.5px Inter;letter-spacing:.1em;color:var(--l)}.dt b{font:600 17px Sora;color:#fff;display:block}.dt p{font-size:15px;color:#d0d0d4}
.dt .r span{display:block}.dt .r>div>small{display:none;font:600 11px Inter;letter-spacing:.1em;color:var(--l);margin-bottom:4px}
/* outcome */
.oc{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.o{background:#fff;border:1px solid var(--line);border-radius:20px;padding:24px;transition:transform .25s,border-color .25s;min-height:190px;display:flex;flex-direction:column}
.o:hover{transform:translateY(-5px);border-color:var(--k)}.o b{font:600 13px Sora;color:var(--mute);margin-bottom:auto;padding-bottom:30px}.o h3{font-size:19px;margin-bottom:6px}.o p{font-size:14.5px}
.o.n{background:var(--k);border-color:var(--k);color:#fff;justify-content:center}.o.n p{color:#d0d0d4;font-size:15px}
/* next */
.nx{display:grid;grid-template-columns:1fr 1.3fr;gap:56px;align-items:center}
.nx h2{font-size:clamp(32px,4.6vw,60px);letter-spacing:-.04em;margin:4px 0 14px}.nx .m{font:600 14px Inter;color:var(--l);margin-bottom:26px}
.nv2{display:flex;gap:18px;justify-content:center;align-items:center;background:var(--k2);border:1px solid var(--dline);border-radius:28px;padding:34px;overflow:hidden}
.nv2 .ph{--pw:170px}.nv2 .ph:nth-child(2){--pw:190px;margin-top:-26px}
.nv2 .pj{--bg:#EDEEF0;--ac:#C7FF3F;--dp:#101114;--im1:#3a3d45;--im2:#101114;--pl:#d9dbe0}
/* cta */
.cta{background:var(--l);color:var(--k);padding:112px 0}.cta h2{font-size:clamp(36px,6.4vw,84px);letter-spacing:-.045em;line-height:1;max-width:900px;margin-bottom:38px}
.cta .fine{color:#3a4400}
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:36px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.ov,.nx{grid-template-columns:1fr;gap:36px}.info{grid-template-columns:repeat(3,1fr);row-gap:20px}
.mp,.fw,.aiflow{grid-template-columns:1fr}.mc,.fs,.an{margin:0 0 30px}.mc:last-child,.fs:last-child,.an:last-child{margin-bottom:0}
.mc::after,.an::after{content:"↓";left:50%;top:100%;transform:translateX(-50%);height:30px;line-height:30px;width:auto}.fs::after{content:"↓";left:50%;top:100%;height:26px;line-height:26px;transform:translateX(-50%);width:auto}
.fs .pj{min-height:0}.dsg{grid-template-columns:1fr 1fr}.dst.w2{grid-column:span 2}
.fr{grid-template-columns:1fr;gap:30px}.fr:nth-of-type(even) .fx{order:0}.fr p{max-width:none}
.tg{grid-template-columns:repeat(3,1fr);row-gap:28px}.oc{grid-template-columns:1fr 1fr}.cols{grid-template-columns:1fr}
.hv .ph{--pw:160px}.fg{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:860px){nav ul{display:none}.dt .hd{display:none}.dt .r{grid-template-columns:1fr;gap:14px}.dt .r>div>small{display:block}}
/* mobile */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding-top:56px}.tags{margin-bottom:40px}
.site .nv span:not(.sr):not(.bt){display:none}.site .nv{padding:12px 16px;gap:10px}.site .hb{margin:14px 16px 0;padding:26px 18px 100px}.site .bk{left:16px;right:16px;grid-template-columns:1fr 1fr}.site .bk .bt{grid-column:span 2;text-align:center}.site .rms{grid-template-columns:1fr 1fr;padding:116px 16px 16px}.site .rms>:last-child{display:none}
.hv{padding-bottom:0}.hv .ph{display:none}.hv .ai{display:none}
.info,.tg,.oc{grid-template-columns:1fr}.dsg{grid-template-columns:1fr}.dst.w2{grid-column:auto}.dsb{padding:14px}.sepn{flex-direction:column;gap:4px}
.pr li{grid-template-columns:44px 1fr}.fv{padding:14px;min-height:0}
.dv{flex-wrap:wrap;padding:18px;gap:14px}.dv .brw{flex:1 1 100%;max-width:none}.dv .tab{--pw:150px}.dv .ph{--pw:100px;border-radius:20px;padding:5px}
.nv2{padding:18px;gap:10px}.nv2 .ph{--pw:112px;border-radius:20px;padding:5px}.nv2 .ph:nth-child(2){--pw:122px;margin-top:0}
.ctas .btn{width:100%;justify-content:center}.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:span 2}.cta{padding:76px 0}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv,.js .mk>span{opacity:1;transform:none}}

js:
(function(){
  var els=document.querySelectorAll('.rv');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(function(e){e.classList.add('in')});return;}
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  els.forEach(function(e){io.observe(e)});
})();
